    p = cell('W1::Coverage', f'C{r}')
    a = cell('W1::Coverage', f'D{r}')
    coverage.setdefault(p, set()).add(a)
req = set(values('W1::Required', 'C42:C45'))
providers = list(costs.keys())
best_cost = None
import itertools
for k in range(1, len(providers) + 1):
    for combo in itertools.combinations(providers, k):
        covered = set()
        c_sum = 0
        for p in combo:
            covered.update(coverage.get(p, set()))
            c_sum += costs[p]
        if req.issubset(covered):
            if best_cost is None or c_sum < best_cost:
                best_cost = c_sum
result = best_cost

